param(
    [Parameter(Mandatory)][ValidateSet('baseline', 'candidate')][string]$Variant
)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$hostRoot = Join-Path $root "$Variant/host"
$runRoot = Join-Path $root "diagnostics/cpu/$Variant/capture-01"
$manifest = Get-Content -LiteralPath (Join-Path $root 'dll-manifest.json') -Raw | ConvertFrom-Json
$expectedDlls = @($manifest.$Variant)
if ($expectedDlls.Count -ne 28) { throw "Expected 28 frozen DLLs for $Variant." }
foreach ($expected in $expectedDlls) {
    $path = Join-Path $hostRoot $expected.Name
    if (-not (Test-Path -LiteralPath $path) -or (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $expected.SHA256) {
        throw "Frozen DLL mismatch: $Variant/$($expected.Name)"
    }
}
$inputPath = Join-Path $hostRoot 'Data/test.json'
if ((Get-FileHash -LiteralPath $inputPath -Algorithm SHA256).Hash -ne 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D') { throw 'Frozen input SHA mismatch.' }
if (Test-Path -LiteralPath $runRoot) { throw "Refusing to overwrite existing CPU capture: $runRoot" }
New-Item -ItemType Directory -Path $runRoot -Force | Out-Null

$psi = [Diagnostics.ProcessStartInfo]::new((Get-Command dotnet).Source)
$psi.WorkingDirectory = $hostRoot
$psi.UseShellExecute = $false
$psi.CreateNoWindow = $true
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
foreach ($arg in @('StringExecutionRecovery.ChildHarness.dll', '--benchmarkName', 'Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput', '--benchmarkId', '0')) { [void]$psi.ArgumentList.Add($arg) }
$psi.Environment['DOTNET_TieredPGO'] = '1'
$psi.Environment['DOTNET_EnableEventPipe'] = '1'
$psi.Environment['DOTNET_EventPipeOutputPath'] = Join-Path $runRoot 'runtime-{pid}.nettrace'
$psi.Environment['DOTNET_EventPipeConfig'] = 'Microsoft-DotNETCore-SampleProfiler:0:5,Microsoft-Windows-DotNETRuntime:1000001019:5,BenchmarkDotNet.EngineEventSource:ffffffffffffffff:5'
$process = [Diagnostics.Process]::Start($psi)
if (-not $process) { throw "Failed to start $Variant CPU diagnostic harness." }
$processId = $process.Id
$process.ProcessorAffinity = [IntPtr]4
if ($process.ProcessorAffinity.ToInt64() -ne 4) { throw 'Affinity was not set to 4.' }
$stdoutTask = $process.StandardOutput.ReadToEndAsync()
$stderrTask = $process.StandardError.ReadToEndAsync()
$startUtc = [DateTime]::UtcNow
$watch = [Diagnostics.Stopwatch]::StartNew()
try {
    while (-not $process.WaitForExit(1000)) {
        if ($watch.Elapsed.TotalSeconds -gt 180) { $process.Kill($true); throw 'CPU diagnostic timed out after 180 seconds.' }
    }
    $exitCode = $process.ExitCode
    $endUtc = [DateTime]::UtcNow
    $stdout = $stdoutTask.GetAwaiter().GetResult()
    $stderr = $stderrTask.GetAwaiter().GetResult()
    [IO.File]::WriteAllText((Join-Path $runRoot 'stdout.log'), $stdout, [Text.UTF8Encoding]::new($false))
    [IO.File]::WriteAllText((Join-Path $runRoot 'stderr.log'), $stderr, [Text.UTF8Encoding]::new($false))
    if ($exitCode -ne 0) { throw "Diagnostic process exit code $exitCode; raw output retained." }
    if ($stderr.Trim().Length -ne 0) { throw 'Diagnostic wrote to stderr; raw output retained.' }
    if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw 'Missing // AfterAll completion marker.' }
    $actual = [regex]::Matches($stdout, '(?m)^WorkloadActual\s+\d+:').Count
    $result = [regex]::Matches($stdout, '(?m)^WorkloadResult\s+\d+:').Count
    $trace = @(Get-ChildItem -LiteralPath $runRoot -Filter 'runtime-*.nettrace')
    if ($trace.Count -ne 1) { throw "Expected one EventPipe trace, found $($trace.Count)." }
    $record = [ordered]@{
        Variant = $Variant
        ProcessId = $processId
        ExitCode = $exitCode
        StartUTC = $startUtc.ToString('o')
        EndUTC = $endUtc.ToString('o')
        WallSeconds = $watch.Elapsed.TotalSeconds
        Affinity = 4
        TieredPGO = 1
        EventPipeConfig = $psi.Environment['DOTNET_EventPipeConfig']
        ActualCount = $actual
        ResultCount = $result
        InputBytes = (Get-Item $inputPath).Length
        InputSHA256 = (Get-FileHash $inputPath -Algorithm SHA256).Hash
        LibrarySHA256 = (Get-FileHash (Join-Path $hostRoot 'Marimo.Kotowari.dll') -Algorithm SHA256).Hash
        ParserSHA256 = (Get-FileHash (Join-Path $hostRoot 'Marimo.Parser.dll') -Algorithm SHA256).Hash
        Trace = [ordered]@{ Name = $trace[0].Name; Bytes = $trace[0].Length; SHA256 = (Get-FileHash $trace[0].FullName -Algorithm SHA256).Hash }
        StdoutBytes = [Text.Encoding]::UTF8.GetByteCount($stdout)
        StderrBytes = [Text.Encoding]::UTF8.GetByteCount($stderr)
        AfterAll = ($stdout -match '(?m)^// AfterAll\s*$')
        DiagnosticOnly = $true
    }
    $record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runRoot 'capture.json') -Encoding utf8
    if ($actual -ne 8 -or $result -ne 8) { throw "Expected 8 Actual and 8 Result windows; got $actual/$result." }
    Write-Output ($record | ConvertTo-Json -Compress)
} finally {
    if (-not $process.HasExited) { $process.Kill($true); $process.WaitForExit() }
    $process.Dispose()
}

# Freeze the DLL hashes for the copied baseline and candidate hosts.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$variants = [ordered]@{}
foreach ($variant in 'baseline', 'candidate') {
    $hostRoot = Join-Path $root "$variant/host"
    $dlls = @(Get-ChildItem -LiteralPath $hostRoot -File -Filter '*.dll' | Sort-Object Name)
    if ($dlls.Count -ne 28) { throw "$variant host must contain exactly 28 DLLs; found $($dlls.Count)." }
    $variants[$variant] = @(
        foreach ($dll in $dlls) {
            [ordered]@{
                Name = $dll.Name
                SHA256 = (Get-FileHash -LiteralPath $dll.FullName -Algorithm SHA256).Hash
            }
        }
    )
}
$differences = @(
    foreach ($baselineDll in $variants.baseline) {
        $candidateDll = $variants.candidate | Where-Object Name -eq $baselineDll.Name
        if (-not $candidateDll -or $candidateDll.SHA256 -ne $baselineDll.SHA256) { $baselineDll.Name }
    }
)
if ($differences.Count -ne 1 -or $differences[0] -ne 'Marimo.Parser.dll') {
    throw "Expected only Marimo.Parser.dll to differ; found: $($differences -join ', ')."
}
if (($variants.candidate | Where-Object Name -eq 'Marimo.Kotowari.dll').SHA256 -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') {
    throw 'Candidate host must retain the fixed baseline Kotowari DLL.'
}
$manifest = [ordered]@{ baseline = $variants.baseline; candidate = $variants.candidate }
$manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $root 'dll-manifest.json') -Encoding utf8
Write-Output "DLL manifest frozen; changed DLL: $($differences[0])."

# Regenerate source hashes for one frozen experiment source tree.
