param(
    [Parameter(Mandatory)][ValidateSet('baseline', 'candidate')][string]$Variant
)

$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$sourceRoot = Join-Path $root "$Variant/source"
$files = @(Get-ChildItem -LiteralPath $sourceRoot -File -Recurse | Sort-Object FullName)
$sourceFiles = @(
    foreach ($file in $files) {
        $relative = [IO.Path]::GetRelativePath($sourceRoot, $file.FullName).Replace('\', '/')
        [ordered]@{
            Path = $relative
            SHA256 = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
        }
    }
)
$record = [ordered]@{
    HEAD = 'd2f7aa8915ca1f580fc009b0a5d88d7b3c9d1ec1'
    Variant = $Variant
    SourceFiles = $sourceFiles
}
$record | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $root "$Variant/source-manifest.json") -Encoding utf8

# Same established JIT capture settings and frozen generated ChildHarness as the baseline capture.
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$hostRoot = Join-Path $root 'candidate/host'
$runRoot = Join-Path $root 'diagnostics/jit/candidate-03'
if (Test-Path $runRoot) { throw "Refusing to overwrite existing capture: $runRoot" }
New-Item -ItemType Directory -Path $runRoot -Force | Out-Null
$dll = Join-Path $hostRoot 'Marimo.Kotowari.dll'
$input = Join-Path $hostRoot 'Data/test.json'
if ((Get-FileHash $dll -Algorithm SHA256).Hash -ne '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8') { throw 'Fixed Kotowari DLL SHA mismatch.' }
if ((Get-FileHash (Join-Path $hostRoot 'Marimo.Parser.dll') -Algorithm SHA256).Hash -ne 'E6265A77370B228E24ACCD2E7C08A2682C227B1E9BFF9DD030E8BB9443F6F820') { throw 'Candidate Parser DLL SHA mismatch.' }
if ((Get-FileHash $input -Algorithm SHA256).Hash -ne 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D') { throw 'Frozen input SHA mismatch.' }
$manifest = Get-Content (Join-Path $root 'dll-manifest.json') -Raw | ConvertFrom-Json
if ($manifest.candidate.Count -ne 28) { throw 'Expected 28 frozen candidate host DLLs.' }
foreach ($item in $manifest.candidate) {
    if ((Get-FileHash (Join-Path $hostRoot $item.Name) -Algorithm SHA256).Hash -ne $item.SHA256) { throw "DLL mismatch: $($item.Name)" }
}
$psi = [Diagnostics.ProcessStartInfo]::new((Get-Command dotnet).Source)
$psi.WorkingDirectory = $hostRoot
$psi.UseShellExecute = $false
$psi.CreateNoWindow = $true
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
foreach ($arg in @('StringExecutionRecovery.ChildHarness.dll','--benchmarkName','Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput','--benchmarkId','0')) { [void]$psi.ArgumentList.Add($arg) }
$psi.Environment['DOTNET_TieredPGO'] = '1'
$psi.Environment['DOTNET_JitDisasm'] = 'Marimo.*!*'
$psi.Environment['DOTNET_JitDisasmWithCodeBytes'] = '1'
$psi.Environment['DOTNET_JitStdOutFile'] = Join-Path $runRoot 'jit.asm'
$process = [Diagnostics.Process]::Start($psi)
if (-not $process) { throw 'Failed to start candidate JIT diagnostic harness.' }
$processId = $process.Id
$process.ProcessorAffinity = [IntPtr]4
if ($process.ProcessorAffinity.ToInt64() -ne 4) { throw 'Affinity was not set to 4.' }
$stdoutTask = $process.StandardOutput.ReadToEndAsync()
$stderrTask = $process.StandardError.ReadToEndAsync()
$startUtc = [DateTime]::UtcNow
$watch = [Diagnostics.Stopwatch]::StartNew()
while (-not $process.WaitForExit(1000)) {
    if ($watch.Elapsed.TotalSeconds -gt 180) { $process.Kill($true); throw 'Candidate JIT diagnostic timed out after 180 seconds.' }
}
$exitCode = $process.ExitCode
$endUtc = [DateTime]::UtcNow
$stdout = $stdoutTask.GetAwaiter().GetResult()
$stderr = $stderrTask.GetAwaiter().GetResult()
[IO.File]::WriteAllText((Join-Path $runRoot 'stdout.log'),$stdout,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $runRoot 'stderr.log'),$stderr,[Text.UTF8Encoding]::new($false))
if ($exitCode -ne 0) { throw "Candidate JIT diagnostic process exit code $exitCode; raw output retained." }
if ($stdout -notmatch '(?m)^// AfterAll\s*$') { throw 'Missing // AfterAll completion marker.' }
$actual = [regex]::Matches($stdout,'(?m)^WorkloadActual\s+\d+:').Count
$result = [regex]::Matches($stdout,'(?m)^WorkloadResult\s+\d+:').Count
$asmPath = Join-Path $runRoot 'jit.asm'
if (-not (Test-Path $asmPath)) { throw 'Candidate JIT disassembly file was not produced.' }
$asm = [IO.File]::ReadAllText($asmPath)
$headers = [regex]::Matches($asm,'(?m)^; Assembly listing for method .+$')
$getterTier1 = @($headers | Where-Object {$_.Value -match 'ParseResult`1\[System\.__Canon\]:get_Parsed\(\).*\(Tier1\)\s*$'}).Count
$record = [ordered]@{ProcessId=$processId;ExitCode=$exitCode;StartUTC=$startUtc.ToString('o');EndUTC=$endUtc.ToString('o');WallSeconds=$watch.Elapsed.TotalSeconds;Affinity=4;TieredPGO=1;JitDisasm='Marimo.*!*';JitDisasmWithCodeBytes=1;WarmupCount=16;ActualCount=$actual;ResultCount=$result;InputBytes=(Get-Item $input).Length;InputSHA256=(Get-FileHash $input -Algorithm SHA256).Hash;LibrarySHA256=(Get-FileHash $dll -Algorithm SHA256).Hash;ParserSHA256=(Get-FileHash (Join-Path $hostRoot 'Marimo.Parser.dll') -Algorithm SHA256).Hash;ChildHarnessSHA256=(Get-FileHash (Join-Path $hostRoot 'StringExecutionRecovery.ChildHarness.dll') -Algorithm SHA256).Hash;JitOutputBytes=(Get-Item $asmPath).Length;JitOutputSHA256=(Get-FileHash $asmPath -Algorithm SHA256).Hash;AssemblyMethodHeaderCount=$headers.Count;ReferenceTypeParsedGetterTier1BlockCount=$getterTier1;StdoutBytes=[Text.Encoding]::UTF8.GetByteCount($stdout);StderrBytes=[Text.Encoding]::UTF8.GetByteCount($stderr);AfterAll=($stdout -match '(?m)^// AfterAll\s*$');DiagnosticOnly=$true;OutputFiles=@('jit.asm','stdout.log','stderr.log')}
$record | ConvertTo-Json -Depth 8 | Set-Content (Join-Path $runRoot 'capture.json') -Encoding utf8
if ($actual -ne 8 -or $result -ne 8) { throw "Expected 8 Actual and 8 Result windows; got $actual/$result." }
Write-Output ($record | ConvertTo-Json -Compress)
